import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 998244353;
    static long[] fact, invFact;

    static long power(long b, long e, long m) {
        long res = 1; b %= m;
        while (e > 0) {
            if ((e & 1) == 1) res = res * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return res;
    }

    static long C(int n, int k) {
        if (k < 0 || n < 0 || k > n) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int p = Integer.parseInt(st.nextToken());
        int s = Integer.parseInt(st.nextToken());
        int r = Integer.parseInt(st.nextToken());

        int N = s + p + 10;
        fact = new long[N];
        invFact = new long[N];
        fact[0] = 1;
        for (int i = 1; i < N; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[N - 1] = power(fact[N - 1], MOD - 2, MOD);
        for (int i = N - 1; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;

        long[] inv = new long[p + 2];
        for (int i = 1; i <= p + 1; i++) inv[i] = power(i, MOD - 2, MOD);

        long ans = 0;

        if (s == 0) {
            // all zeros, only state
            // r must be 0
            ans = inv[p];
            System.out.println(ans % MOD);
            return;
        }

        int start = Math.max(r, 1);
        for (int m = start; m <= s; m++) {
            for (int k = 0; k <= p - 1; k++) {
                long used = (long) m * (k + 1);
                if (used > s) break;
                int rem = (int) (s - used);
                int j = p - 1 - k;
                long cnt;
                if (j == 0) {
                    cnt = (rem == 0) ? 1 : 0;
                } else {
                    // number of ways j players each in [0, m-1] sum to rem
                    long tot = 0;
                    int maxI = Math.min(j, rem / m);
                    for (int i = 0; i <= maxI; i++) {
                        long term = C(j, i) * C(rem - i * m + j - 1, j - 1) % MOD;
                        if ((i & 1) == 0) tot = (tot + term) % MOD;
                        else tot = (tot - term + MOD) % MOD;
                    }
                    cnt = tot;
                }
                if (cnt == 0) continue;
                long contrib = C(p - 1, k) * cnt % MOD * inv[k + 1] % MOD;
                ans = (ans + contrib) % MOD;
            }
        }

        long total = C(s - r + p - 1, p - 1);
        long res = ans * power(total, MOD - 2, MOD) % MOD;
        System.out.println(res);
    }
}
